async function cloud148(path,opts={}){const headers={...(opts.headers||{}),Authorization:'Bearer '+token()};if(opts.body&&!headers['Content-Type'])headers['Content-Type']='application/json';const r=await fetch(API+path,{...opts,headers,cache:'no-store'}),x=await r.json().catch(()=>({}));if(!r.ok||x.ok===false)throw new Error(x.error||'Cloud-Anfrage fehlgeschlagen.');return x}
