function markdown148(src){const lines=String(src||'').replace(/\r\n?/g,'\n').split('\n');let html='',list=null,seenH1=false;const close=()=>{if(list){html+=`</${list}>`;list=null}};for(const raw of lines){const line=raw.trimEnd();if(!line.trim()){close();continue}let m;if((m=line.match(/^#\s+(.+)$/))){close();if(!seenH1){seenH1=true;continue}html+=`<h2>${inline148(m[1])}</h2>`;continue}if((m=line.match(/^##\s+(.+)$/))){close();html+=`<h2>${inline148(m[1])}</h2>`;continue}if((m=line.match(/^###\s+(.+)$/))){close();html+=`<h3>${inline148(m[1])}</h3>`;continue}if((m=line.match(/^[-*]\s+(.+)$/))){if(list!=='ul'){close();list='ul';html+='<ul>'}html+=`<li>${inline148(m[1])}</li>`;continue}if((m=line.match(/^\d+\.\s+(.+)$/))){if(list!=='ol'){close();list='ol';html+='<ol>'}html+=`<li>${inline148(m[1])}</li>`;continue}if((m=line.match(/^>\s?(.*)$/))){close();html+=`<blockquote>${inline148(m[1])}</blockquote>`;continue}close();html+=`<p>${inline148(line)}</p>`}close();return html}
