function sourceLabel148(c){const generic=new Set(['book','web','own','other','workshop','conversation','training','youtube','reddit','quelle','source','buch']);const candidate=[c.sourceDescription,c.title].map(x=>String(x||'').trim()).find(x=>x&&!generic.has(x.toLowerCase()));if(candidate)return candidate.slice(0,300);try{const u=new URL(c.sourceUrl);if(['http:','https:'].includes(u.protocol))return u.hostname.replace(/^www\./,'')}catch(_){}return ''}
